        'mao': { name: 'Sneaky Hand', say: 'PSST... PSST...', text: 'The Hairy Hand dropped what it had grabbed.' },
        'cuia': { name: 'Rolling Gourd', say: 'ROLL, GOURD!', text: 'The Gourd Head rolled by and left firewood behind.' },
        'boto': { name: 'Dancing Boto', say: 'SHALL WE DANCE?', text: 'One dance with the Boto and hearts felt light.' },
        'veado': { name: 'White Deer', say: 'THE WHITE DEER!', text: 'The Anhangá looked after the animals and the Cassava’s belly.' },
        'boi': { name: 'Black-faced Bull', say: 'SLEEP, LITTLE ONE...', text: 'The bull sang a lullaby and the party got tickets.' },
        'pisadeira': { name: 'Pisadeira on the Pole', say: 'OOOH... GET DOWN!', text: 'The Pisadeira fled the pole and left some Cheer.' },
        'saco': { name: 'Sack Man', say: 'RUN, KIDS!', text: 'The Sack Man dropped the sack and ran off.' },
        'seco': { name: 'Dry Body', say: 'DRY... SO DRY...', text: 'The Dry Body crumbled to dust and left dry firewood.' },
        'curupira': { name: 'Curupira’s Footprints', say: 'BACKWARDS FOOTPRINTS!', text: 'The Curupira blessed the party before vanishing into the woods.' },
        'caipora': { name: 'Caipora Rides By', say: 'TOBACCO, TOBACCO!', text: 'The Caipora tossed firewood from her wild boar.' },
        'iara': { name: 'Iara’s Song', say: 'HEAR THE SONG...', text: 'The Iara sang and the whole party fell in love.' },
        'boitata': { name: 'Boitatá at the Bonfire', say: 'FIRE IN THE WOODS!', text: 'The Boitatá stoked the bonfire and left wood and embers.' },
        'mula': { name: 'Mule Gallop', say: 'CLIP-CLOP-CLIP!', text: 'The Headless Mule lost a lucky horseshoe.' },
        'lobisomem': { name: 'Howl at the Moon', say: 'AWOOOOOO!', text: 'The Werewolf howled and the party got pumped up.' },
        'cuca': { name: 'Cuca’s Cauldron', say: 'HEE HEE HEE HEE!', text: 'The Cuca stirred her cauldron and a potion came out.' },
        'mapinguari': { name: 'Mapinguari Stench', say: 'WHAT A STINK!', text: 'The Mapinguari dropped a peanut brittle and left.' },
        'boiuna': { name: 'Boiúna’s Eyes', say: 'LANTERN EYES!', text: 'The Boiúna blinked its eyes and tickets slid out.' },
        'bumba': { name: 'Dancing Boi-Bumbá', say: 'LONG LIVE THE BULL!', text: 'The Boi-Bumbá brought the whole party back to life.' },
        'desfile': { name: 'Enchanted Parade', say: 'ENCHANTED PARADE!', text: 'The whole folklore bunch paraded through the party.' },
